window.DV_TOPICS=window.DV_TOPICS||{};window.DV_TOPICS["streaming-vs-cinema"]={"id":"streaming-vs-cinema","order":20,"title_en":"Streaming vs Cinema","title_zh":"流媒体与影院","blurb_zh":"屏幕时间怎么挤走影院","scene_zh":"成年人的每周娱乐时间调查（模拟数据）","views":[{"id":"weekly","type":"line","label_zh":"每周时长","label_en":"Weekly hours","subject":"Weekly leisure time with streaming and cinema","subtitle_en":"Average hours per week, 2019 to 2026.","unit":{"en":"hours per week","short":"h","decimals":1,"kind":"count"},"data":{"x":{"label_en":"Year","label_zh":"年份","values":["2019","2020","2021","2022","2023","2024","2025","2026"]},"series":[{"id":"streaming","name_en":"Streaming","name_zh":"流媒体","slot":1,"values":[5.0,8.5,9.2,10.4,11.0,11.6,12.1,12.4]},{"id":"cinema","name_en":"Cinema","name_zh":"影院","slot":2,"values":[1.6,0.4,0.7,0.9,1.0,1.1,1.2,1.3]}]},"features":[{"kind":"rise_sharp","marks":["seg:streaming:0"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2019 to 2020","series_name":"Streaming","from":"5 hours per week","to":"8.5 hours per week","from_period":"2019","to_period":"2020","pct":"70","pp":"3.5","delta":"3.5 hours per week"},"auto":false,"id":"sc-jump","examples":[{"en":"Streaming time jumped from 5.0 hours a week in 2019 to 8.5 in 2020.","zh":"流媒体每周时长从 2019 年的 5.0 小时跳到 2020 年的 8.5 小时。"}],"note_zh":"jump from ... to ... 强调一年内的大幅变化。","interpret_zh":"第一年就涨了 70%，是整段里最快的一次。"},{"kind":"rise_slight","marks":["seg:streaming:1"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2020 to 2021","series_name":"Streaming","from":"8.5 hours per week","to":"9.2 hours per week","from_period":"2020","to_period":"2021","pct":"8.2","pp":"0.7","delta":"0.7 hours per week"},"auto":true},{"kind":"rise_steady","marks":["seg:streaming:2"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2021 to 2022","series_name":"Streaming","from":"9.2 hours per week","to":"10.4 hours per week","from_period":"2021","to_period":"2022","pct":"13","pp":"1.2","delta":"1.2 hours per week"},"auto":false,"id":"sc-steady","examples":[{"en":"From 2021 to 2022, streaming rose steadily from 9.2 to 10.4 hours.","zh":"2021 到 2022 年，流媒体从 9.2 小时稳步升到 10.4 小时。"}],"note_zh":"rise steadily 说节奏稳定，不强调幅度。","interpret_zh":"这一段的增幅约 13%，低于第一年。"},{"kind":"rise_slight","marks":["seg:streaming:3"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2022 to 2023","series_name":"Streaming","from":"10.4 hours per week","to":"11 hours per week","from_period":"2022","to_period":"2023","pct":"5.8","pp":"0.6","delta":"0.6 hours per week"},"auto":true},{"kind":"rise_slight","marks":["seg:streaming:4"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2023 to 2024","series_name":"Streaming","from":"11 hours per week","to":"11.6 hours per week","from_period":"2023","to_period":"2024","pct":"5.5","pp":"0.6","delta":"0.6 hours per week"},"auto":true},{"kind":"rise_slight","marks":["seg:streaming:5"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2024 to 2025","series_name":"Streaming","from":"11.6 hours per week","to":"12.1 hours per week","from_period":"2024","to_period":"2025","pct":"4.3","pp":"0.5","delta":"0.5 hours per week"},"auto":true},{"kind":"flat","marks":["seg:streaming:6"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2025 to 2026","series_name":"Streaming","from":"12.1 hours per week","to":"12.4 hours per week","from_period":"2025","to_period":"2026","pct":"2.5","pp":"0.3","delta":"0.3 hours per week"},"auto":false,"id":"sc-flat","examples":[{"en":"Streaming stayed nearly flat in 2026, moving only from 12.1 to 12.4 hours.","zh":"2026 年流媒体几乎持平，只从 12.1 小时微增到 12.4 小时。"}],"note_zh":"nearly flat 比 flat 更准确，因为仍有小幅变化。","interpret_zh":"增长放缓，但还没有出现下降。"},{"kind":"trough","marks":["pt:streaming:0"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2019","series_name":"Streaming","value":"5 hours per week","peak":"12.4 hours per week","peak_period":"2026"},"auto":true},{"kind":"point","marks":["pt:streaming:1"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2020","series_name":"Streaming","value":"8.5 hours per week","peak":"12.4 hours per week","peak_period":"2026"},"auto":true},{"kind":"point","marks":["pt:streaming:2"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2021","series_name":"Streaming","value":"9.2 hours per week","peak":"12.4 hours per week","peak_period":"2026"},"auto":true},{"kind":"point","marks":["pt:streaming:3"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2022","series_name":"Streaming","value":"10.4 hours per week","peak":"12.4 hours per week","peak_period":"2026"},"auto":true},{"kind":"point","marks":["pt:streaming:4"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2023","series_name":"Streaming","value":"11 hours per week","peak":"12.4 hours per week","peak_period":"2026"},"auto":true},{"kind":"point","marks":["pt:streaming:5"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2024","series_name":"Streaming","value":"11.6 hours per week","peak":"12.4 hours per week","peak_period":"2026"},"auto":true},{"kind":"point","marks":["pt:streaming:6"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2025","series_name":"Streaming","value":"12.1 hours per week","peak":"12.4 hours per week","peak_period":"2026"},"auto":true},{"kind":"peak","marks":["pt:streaming:7"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2026","series_name":"Streaming","value":"12.4 hours per week","peak":"12.4 hours per week","peak_period":"2026"},"auto":false,"id":"sc-peak","examples":[{"en":"Streaming peaked at 12.4 hours a week in 2026.","zh":"流媒体在 2026 年达到每周 12.4 小时的峰值。"}],"note_zh":"peak at + 数值 是最简洁的动词用法。","interpret_zh":"峰值仍在缓慢上升，但最后一年几乎走平。"},{"kind":"fall_sharp","marks":["seg:cinema:0"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2019 to 2020","series_name":"Cinema","from":"1.6 hours per week","to":"0.4 hours per week","from_period":"2019","to_period":"2020","pct":"75","pp":"1.2","delta":"1.2 hours per week"},"auto":true},{"kind":"rise_sharp","marks":["seg:cinema:1"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2020 to 2021","series_name":"Cinema","from":"0.4 hours per week","to":"0.7 hours per week","from_period":"2020","to_period":"2021","pct":"75","pp":"0.3","delta":"0.3 hours per week"},"auto":false,"id":"sc-cinema-back","examples":[{"en":"Cinema time rebounded sharply from 0.4 to 0.7 hours between 2020 and 2021.","zh":"影院时长在 2020 到 2021 年间从 0.4 小时反弹到 0.7 小时。"}],"note_zh":"rebound 指跌后回升，比 rise 多一层方向信息。","interpret_zh":"涨幅 75%，但起点极低，实际只多了 18 分钟。"},{"kind":"rise_sharp","marks":["seg:cinema:2"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2021 to 2022","series_name":"Cinema","from":"0.7 hours per week","to":"0.9 hours per week","from_period":"2021","to_period":"2022","pct":"29","pp":"0.2","delta":"0.2 hours per week"},"auto":true},{"kind":"rise_steady","marks":["seg:cinema:3"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2022 to 2023","series_name":"Cinema","from":"0.9 hours per week","to":"1 hours per week","from_period":"2022","to_period":"2023","pct":"11","pp":"0.1","delta":"0.1 hours per week"},"auto":true},{"kind":"rise_steady","marks":["seg:cinema:4"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2023 to 2024","series_name":"Cinema","from":"1 hours per week","to":"1.1 hours per week","from_period":"2023","to_period":"2024","pct":"10","pp":"0.1","delta":"0.1 hours per week"},"auto":true},{"kind":"rise_slight","marks":["seg:cinema:5"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2024 to 2025","series_name":"Cinema","from":"1.1 hours per week","to":"1.2 hours per week","from_period":"2024","to_period":"2025","pct":"9.1","pp":"0.1","delta":"0.1 hours per week"},"auto":true},{"kind":"rise_slight","marks":["seg:cinema:6"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2025 to 2026","series_name":"Cinema","from":"1.2 hours per week","to":"1.3 hours per week","from_period":"2025","to_period":"2026","pct":"8.3","pp":"0.1","delta":"0.1 hours per week"},"auto":true},{"kind":"peak","marks":["pt:cinema:0"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2019","series_name":"Cinema","value":"1.6 hours per week","peak":"1.6 hours per week","peak_period":"2019"},"auto":true},{"kind":"trough","marks":["pt:cinema:1"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2020","series_name":"Cinema","value":"0.4 hours per week","peak":"1.6 hours per week","peak_period":"2019"},"auto":false,"id":"sc-cinema-trough","examples":[{"en":"Cinema time bottomed out in 2020 at 0.4 hours a week.","zh":"影院每周时长在 2020 年触底，仅 0.4 小时。"}],"note_zh":"bottom out 暗示之后可能回升，常配 in + 年份。","interpret_zh":"0.4 小时约合每月不到两小时，接近停摆。"},{"kind":"point","marks":["pt:cinema:2"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2021","series_name":"Cinema","value":"0.7 hours per week","peak":"1.6 hours per week","peak_period":"2019"},"auto":true},{"kind":"point","marks":["pt:cinema:3"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2022","series_name":"Cinema","value":"0.9 hours per week","peak":"1.6 hours per week","peak_period":"2019"},"auto":true},{"kind":"point","marks":["pt:cinema:4"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2023","series_name":"Cinema","value":"1 hours per week","peak":"1.6 hours per week","peak_period":"2019"},"auto":true},{"kind":"point","marks":["pt:cinema:5"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2024","series_name":"Cinema","value":"1.1 hours per week","peak":"1.6 hours per week","peak_period":"2019"},"auto":true},{"kind":"point","marks":["pt:cinema:6"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2025","series_name":"Cinema","value":"1.2 hours per week","peak":"1.6 hours per week","peak_period":"2019"},"auto":true},{"kind":"peak","marks":["pt:cinema:7"],"slots":{"subject":"Weekly leisure time with streaming and cinema","unit":"h","category":"","period":"2026","series_name":"Cinema","value":"1.3 hours per week","peak":"1.6 hours per week","peak_period":"2019"},"auto":true}],"overview_zh":"流媒体每周时长从 5.0 小时升到 12.4 小时，2020 年跳升最快，最后一年几乎走平；影院从 1.6 小时跌到 0.4 小时后缓慢回升到 1.3 小时，始终没有恢复。","descriptions":{"general":{"a2":"Streaming time grew from 5 hours a week in 2019 to 12.4 hours in 2026. Cinema time fell from 1.6 hours to 0.4 in 2020 and then rose slowly. Most of the growth in streaming came early.","b1":"Streaming rose from 5.0 hours a week in 2019 to 12.4 in 2026. Cinema collapsed from 1.6 to 0.4 hours in 2020 and recovered only slowly, reaching 1.3 hours. Streaming's sharpest jump came in the first year.","b2":"Streaming time more than doubled over the period, from 5.0 to 12.4 hours a week, with the steepest gain in 2020. Cinema dropped from 1.6 to 0.4 hours that year and has recovered to just 1.3. The two lines have never come close to meeting again."},"ielts":"Weekly streaming time rose from 5.0 hours in 2019 to 12.4 hours in 2026, with a sharp increase in 2020. Cinema time fell from 1.6 to 0.4 hours that year and then recovered gradually to 1.3 hours.","business":"Streaming has taken the growth and cinema has not recovered. Weekly streaming hours more than doubled to 12.4, while cinema sits at 1.3, below its 2019 level. The gap is now structural, not seasonal."}},{"id":"mix","type":"slope","label_zh":"休闲构成","label_en":"Leisure mix","subject":"Share of leisure time by activity","subtitle_en":"Share of leisure time in 2020 and 2026.","unit":{"en":"percent","short":"%","decimals":0,"kind":"percent","points":true},"data":{"periods":[{"id":"p2020","label_en":"2020"},{"id":"p2026","label_en":"2026"}],"entities":[{"id":"streaming","name_en":"Streaming","name_zh":"流媒体","slot":1,"values":[22,31]},{"id":"short_video","name_en":"Short video","name_zh":"短视频","slot":2,"values":[18,35]},{"id":"gaming","name_en":"Gaming","name_zh":"游戏","slot":3,"values":[13,11]},{"id":"social_media","name_en":"Social media","name_zh":"社交媒体","slot":4,"values":[20,13]},{"id":"reading","name_en":"Reading","name_zh":"阅读","slot":5,"values":[9,5]},{"id":"out_of_home","name_en":"Out-of-home","name_zh":"线下休闲","slot":6,"values":[18,5]}]},"features":[{"kind":"rank_down","marks":["line:streaming"],"slots":{"subject":"Share of leisure time by activity","entity":"Streaming","category":"Streaming","from":"22 percent","to":"31 percent","from_period":"2020","to_period":"2026","period":"2020 to 2026","pct":"41","pp":"9","delta":"9 percentage points","rank":"2","rank_before":"1","gap":"1"},"auto":false,"id":"scs-streaming","examples":[{"en":"Streaming grew from 22 to 31 percent but fell from first to second.","zh":"流媒体从 22% 增至 31%，名次却从第一跌到第二。"}],"note_zh":"数值上升与名次下降可以同时发生，用 but 连接。","interpret_zh":"自身在涨，只是对手涨得更快。"},{"kind":"point","marks":["pt:streaming:0"],"slots":{"subject":"Share of leisure time by activity","entity":"Streaming","category":"Streaming","from":"22 percent","to":"31 percent","from_period":"2020","to_period":"2026","period":"2020","pct":"41","pp":"9","delta":"9 percentage points","rank":"1","rank_before":"1","gap":"1","value":"22 percent"},"auto":true},{"kind":"point","marks":["pt:streaming:1"],"slots":{"subject":"Share of leisure time by activity","entity":"Streaming","category":"Streaming","from":"22 percent","to":"31 percent","from_period":"2020","to_period":"2026","period":"2026","pct":"41","pp":"9","delta":"9 percentage points","rank":"2","rank_before":"1","gap":"1","value":"31 percent"},"auto":true},{"kind":"overtake","marks":["line:short_video"],"slots":{"subject":"Share of leisure time by activity","entity":"Short video","category":"Short video","from":"18 percent","to":"35 percent","from_period":"2020","to_period":"2026","period":"2020 to 2026","pct":"94","pp":"17","delta":"17 percentage points","rank":"1","rank_before":"3","gap":"2"},"auto":false,"id":"scs-short","examples":[{"en":"Short video rose from 18 to 35 percent and overtook streaming for the top spot.","zh":"短视频从 18% 升到 35%，反超流媒体登顶。"}],"note_zh":"overtake 及物，直接跟对手，不加 to。","interpret_zh":"起点并列第三，六年后领先第二名 4 个百分点。"},{"kind":"point","marks":["pt:short_video:0"],"slots":{"subject":"Share of leisure time by activity","entity":"Short video","category":"Short video","from":"18 percent","to":"35 percent","from_period":"2020","to_period":"2026","period":"2020","pct":"94","pp":"17","delta":"17 percentage points","rank":"3","rank_before":"3","gap":"2","value":"18 percent"},"auto":true},{"kind":"point","marks":["pt:short_video:1"],"slots":{"subject":"Share of leisure time by activity","entity":"Short video","category":"Short video","from":"18 percent","to":"35 percent","from_period":"2020","to_period":"2026","period":"2026","pct":"94","pp":"17","delta":"17 percentage points","rank":"1","rank_before":"3","gap":"2","value":"35 percent"},"auto":false,"id":"scs-point","examples":[{"en":"In 2026, short video took 35 percent of leisure time.","zh":"2026 年，短视频占休闲时间的 35%。"}],"note_zh":"take + 百分比 + of 说占比，口语常用。","interpret_zh":"超过三分之一，但不代表具体每天多少分钟。"},{"kind":"rank_up","marks":["line:gaming"],"slots":{"subject":"Share of leisure time by activity","entity":"Gaming","category":"Gaming","from":"13 percent","to":"11 percent","from_period":"2020","to_period":"2026","period":"2020 to 2026","pct":"15","pp":"2","delta":"2 percentage points","rank":"4","rank_before":"5","gap":"1"},"auto":false,"id":"scs-gaming","examples":[{"en":"Gaming slipped from 13 to 11 percent but moved from fifth to fourth.","zh":"游戏从 13% 降到 11%，名次却从第五升到第四。"}],"note_zh":"slip 指小幅下滑，比 fall 轻。","interpret_zh":"游戏份额略降，名次上升是因为阅读和线下休闲跌得更多。"},{"kind":"point","marks":["pt:gaming:0"],"slots":{"subject":"Share of leisure time by activity","entity":"Gaming","category":"Gaming","from":"13 percent","to":"11 percent","from_period":"2020","to_period":"2026","period":"2020","pct":"15","pp":"2","delta":"2 percentage points","rank":"5","rank_before":"5","gap":"1","value":"13 percent"},"auto":true},{"kind":"point","marks":["pt:gaming:1"],"slots":{"subject":"Share of leisure time by activity","entity":"Gaming","category":"Gaming","from":"13 percent","to":"11 percent","from_period":"2020","to_period":"2026","period":"2026","pct":"15","pp":"2","delta":"2 percentage points","rank":"4","rank_before":"5","gap":"1","value":"11 percent"},"auto":true},{"kind":"rank_down","marks":["line:social_media"],"slots":{"subject":"Share of leisure time by activity","entity":"Social media","category":"Social media","from":"20 percent","to":"13 percent","from_period":"2020","to_period":"2026","period":"2020 to 2026","pct":"35","pp":"7","delta":"7 percentage points","rank":"3","rank_before":"2","gap":"1"},"auto":true},{"kind":"point","marks":["pt:social_media:0"],"slots":{"subject":"Share of leisure time by activity","entity":"Social media","category":"Social media","from":"20 percent","to":"13 percent","from_period":"2020","to_period":"2026","period":"2020","pct":"35","pp":"7","delta":"7 percentage points","rank":"2","rank_before":"2","gap":"1","value":"20 percent"},"auto":true},{"kind":"point","marks":["pt:social_media:1"],"slots":{"subject":"Share of leisure time by activity","entity":"Social media","category":"Social media","from":"20 percent","to":"13 percent","from_period":"2020","to_period":"2026","period":"2026","pct":"35","pp":"7","delta":"7 percentage points","rank":"3","rank_before":"2","gap":"1","value":"13 percent"},"auto":true},{"kind":"rank_up","marks":["line:reading"],"slots":{"subject":"Share of leisure time by activity","entity":"Reading","category":"Reading","from":"9 percent","to":"5 percent","from_period":"2020","to_period":"2026","period":"2020 to 2026","pct":"44","pp":"4","delta":"4 percentage points","rank":"5","rank_before":"6","gap":"1"},"auto":false,"id":"scs-reading","examples":[{"en":"Reading shrank from 9 to 5 percent yet moved up from sixth to fifth.","zh":"阅读从 9% 缩到 5%，名次却从第六升到第五。"}],"note_zh":"shrank 是 shrink 的过去式；yet 引出反差。","interpret_zh":"名次上升只是因为线下休闲跌得更狠。"},{"kind":"point","marks":["pt:reading:0"],"slots":{"subject":"Share of leisure time by activity","entity":"Reading","category":"Reading","from":"9 percent","to":"5 percent","from_period":"2020","to_period":"2026","period":"2020","pct":"44","pp":"4","delta":"4 percentage points","rank":"6","rank_before":"6","gap":"1","value":"9 percent"},"auto":true},{"kind":"point","marks":["pt:reading:1"],"slots":{"subject":"Share of leisure time by activity","entity":"Reading","category":"Reading","from":"9 percent","to":"5 percent","from_period":"2020","to_period":"2026","period":"2026","pct":"44","pp":"4","delta":"4 percentage points","rank":"5","rank_before":"6","gap":"1","value":"5 percent"},"auto":true},{"kind":"rank_down","marks":["line:out_of_home"],"slots":{"subject":"Share of leisure time by activity","entity":"Out-of-home","category":"Out-of-home","from":"18 percent","to":"5 percent","from_period":"2020","to_period":"2026","period":"2020 to 2026","pct":"72","pp":"13","delta":"13 percentage points","rank":"6","rank_before":"4","gap":"2"},"auto":false,"id":"scs-out","examples":[{"en":"Out-of-home leisure fell from 18 to 5 percent, dropping from fourth to last.","zh":"线下休闲从 18% 降到 5%，从第四跌到最后。"}],"note_zh":"fall from ... to ... 说数值；dropping from ... to ... 说名次。","interpret_zh":"线下时间的绝对量可能没变，这里只是份额。"},{"kind":"point","marks":["pt:out_of_home:0"],"slots":{"subject":"Share of leisure time by activity","entity":"Out-of-home","category":"Out-of-home","from":"18 percent","to":"5 percent","from_period":"2020","to_period":"2026","period":"2020","pct":"72","pp":"13","delta":"13 percentage points","rank":"4","rank_before":"4","gap":"2","value":"18 percent"},"auto":true},{"kind":"point","marks":["pt:out_of_home:1"],"slots":{"subject":"Share of leisure time by activity","entity":"Out-of-home","category":"Out-of-home","from":"18 percent","to":"5 percent","from_period":"2020","to_period":"2026","period":"2026","pct":"72","pp":"13","delta":"13 percentage points","rank":"6","rank_before":"4","gap":"2","value":"5 percent"},"auto":true}],"overview_zh":"短视频从 18% 涨到 35% 登顶，流媒体从 22% 涨到 31% 退居第二；游戏、社交媒体、阅读和线下休闲全部缩水，休闲时间向屏幕集中。","descriptions":{"general":{"a2":"Short video became the biggest use of leisure time, growing from 18 to 35 percent. Streaming also grew, but only to second place. Out-of-home activities and reading became much smaller.","b1":"Short video rose from 18 to 35 percent between 2020 and 2026, taking first place from streaming. Streaming still grew, from 22 to 31 percent. Gaming, social media, reading and out-of-home activities all lost share.","b2":"Leisure time consolidated around two screen activities: short video climbed from 18 to 35 percent while streaming rose from 22 to 31. Together they account for two-thirds of leisure time. Out-of-home activities fell from 18 to 5 percent and reading from 9 to 5."},"ielts":"Short video more than doubled its share of leisure time, from 18 percent in 2020 to 35 percent in 2026, overtaking streaming. Streaming itself rose from 22 to 31 percent, while out-of-home activities fell from 18 to 5 percent.","business":"Leisure demand is concentrating on short video and streaming, which now hold 66 percent combined. The collapse of out-of-home leisure, from 18 to 5 percent, is the sharper signal for advertisers planning offline inventory."}}]};
